import{_ as h,o as t,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Hệ thống Bảo đảm Mọi người đều có Đường","description":"","frontmatter":{},"headers":[],"relativePath":"vi/0008-人人有路保障体系.md","filePath":"vi/0008-人人有路保障体系.md"}'),g={name:"vi/0008-人人有路保障体系.md"};function a(u,n,o,l,m,r){return t(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="he-thong-bao-đam-moi-nguoi-đeu-co-đuong" tabindex="-1">Hệ thống Bảo đảm Mọi người đều có Đường <a class="header-anchor" href="#he-thong-bao-đam-moi-nguoi-đeu-co-đuong" aria-label="Permalink to &quot;Hệ thống Bảo đảm Mọi người đều có Đường&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>08</td></tr><tr><td>Mô-đun</td><td>Nguyên tắc chung và Cài đặt cốt lõi</td></tr><tr><td>Từ khóa chính</td><td>Mọi người đều có Đường, Hệ thống Bảo đảm, Đường cơ bản Tiến hóa, Nhóm dễ bị tổn thương, Phổ quát</td></tr></tbody></table><h2 id="_1-đinh-nghia-co-ban-ve-moi-nguoi-đeu-co-đuong" tabindex="-1">1. Định nghĩa cơ bản về Mọi người đều có Đường <a class="header-anchor" href="#_1-đinh-nghia-co-ban-ve-moi-nguoi-đeu-co-đuong" aria-label="Permalink to &quot;1. Định nghĩa cơ bản về Mọi người đều có Đường&quot;">​</a></h2><p>Mọi người đều có đường là một trong những mục tiêu xã hội cốt lõi của Văn minh Cộng sinh Neo, có nghĩa là đảm bảo rằng mỗi sự sống trong Heng Yuan Zhou, bất kể chủng tộc, xuất thân, tài năng, cấp độ, hay tình trạng giàu có của mình, đều có thể có được một con đường tiến hóa phù hợp với bản thân, và có cơ hội đạt được sự nâng cao cấp độ và sự hoàn thiện của cuộc sống thông qua nỗ lực của chính mình. &quot;Có đường&quot; không chỉ có nghĩa là có pháp môn tu luyện để học, mà còn có nghĩa là có tài nguyên để sử dụng, có cố vấn để hỏi, có môi trường để tu luyện, và có thể chế để dựa vào.</p><p>Mọi người đều có đường và Nhiều lao động Nhiều thưởng là hai trụ cột của hệ thống phân phối văn minh cộng sinh. Nhiều lao động Nhiều thưởng giải quyết vấn đề &quot;hiệu quả&quot;, khuyến khích người mạnh tạo ra nhiều giá trị hơn; Mọi người đều có đường giải quyết vấn đề &quot;công bằng&quot;, đảm bảo người yếu không bị hệ thống tiến hóa bỏ rơi. Cả hai bổ sung cho nhau, và không cái nào hoàn chỉnh nếu thiếu cái kia. Không có Mọi người đều có đường, Nhiều lao động Nhiều thưởng sẽ thoái hóa thành luật rừng; không có Nhiều lao động Nhiều thưởng, Mọi người đều có đường sẽ thoái hóa thành bình quân chủ nghĩa.</p><h2 id="_2-su-can-thiet-cua-moi-nguoi-đeu-co-đuong" tabindex="-1">2. Sự cần thiết của Mọi người đều có Đường <a class="header-anchor" href="#_2-su-can-thiet-cua-moi-nguoi-đeu-co-đuong" aria-label="Permalink to &quot;2. Sự cần thiết của Mọi người đều có Đường&quot;">​</a></h2><p>Việc thành lập hệ thống bảo đảm Mọi người đều có đường dựa trên nhận thức sâu sắc sau:</p><h3 id="_2-1-quyen-tien-hoa-la-quyen-song-co-ban-nhat" tabindex="-1">2.1 Quyền tiến hóa là quyền sống cơ bản nhất <a class="header-anchor" href="#_2-1-quyen-tien-hoa-la-quyen-song-co-ban-nhat" aria-label="Permalink to &quot;2.1 Quyền tiến hóa là quyền sống cơ bản nhất&quot;">​</a></h3><p>Trong văn minh tu luyện, quyền tiến hóa không chỉ là quyền phát triển, mà còn là quyền sống. Sự sống cấp độ thấp, khi đối mặt với các nguy hiểm khác nhau trong vũ trụ (như biến động vị diện, bão năng lượng, xâm lược chủng tộc ngoại lai, v.v.), có xác suất sống sót thấp hơn nhiều so với sự sống cấp độ cao. Do đó, đảm bảo mỗi sự sống đều có con đường tiến hóa, về bản chất là đảm bảo quyền sống cơ bản của mỗi sự sống.</p><h3 id="_2-2-su-khac-biet-ve-tai-nang-ban-đau-khong-nen-quyet-đinh-so-phan-tien-hoa" tabindex="-1">2.2 Sự khác biệt về tài năng ban đầu không nên quyết định số phận tiến hóa <a class="header-anchor" href="#_2-2-su-khac-biet-ve-tai-nang-ban-đau-khong-nen-quyet-đinh-so-phan-tien-hoa" aria-label="Permalink to &quot;2.2 Sự khác biệt về tài năng ban đầu không nên quyết định số phận tiến hóa&quot;">​</a></h3><p>Mỗi sự sống có sự khác biệt lớn về tài năng ban đầu (tài năng chủng tộc, nền tảng gia đình, vị diện sinh ra, năng khiếu bẩm sinh, v.v.). Trong thời đại chủ nghĩa cướp bóc, sự khác biệt này thường được phóng đại thành vực thẳm không thể vượt qua — sự sống có xuất thân tốt độc quyền tài nguyên chất lượng, trong khi sự sống có xuất thân xấu thậm chí không thể có được pháp môn tu luyện cơ bản. Văn minh cộng sinh tin rằng sự khác biệt về tài năng ban đầu tồn tại một cách khách quan, nhưng không nên là yếu tố duy nhất quyết định số phận tiến hóa. Vai trò của thể chế là bù đắp cho sự khác biệt ban đầu này, và cho mỗi sự sống cơ hội thay đổi số phận thông qua nỗ lực có được sau này.</p><h3 id="_2-3-cac-ca-nhan-bi-bo-roi-la-ton-that-tiem-an-cho-van-minh" tabindex="-1">2.3 Các cá nhân bị bỏ rơi là tổn thất tiềm ẩn cho văn minh <a class="header-anchor" href="#_2-3-cac-ca-nhan-bi-bo-roi-la-ton-that-tiem-an-cho-van-minh" aria-label="Permalink to &quot;2.3 Các cá nhân bị bỏ rơi là tổn thất tiềm ẩn cho văn minh&quot;">​</a></h3><p>Mỗi sự sống đều có tiềm năng tiến hóa, và nhiều khi chỉ thiếu con đường và tài nguyên phù hợp. Một sự sống đang đấu tranh ở tầng đáy có thể thể hiện tài năng đáng ngạc nhiên sau khi có được hệ thống tu luyện phù hợp; một cá nhân bị coi là &quot;vô dụng&quot; có thể chỉ là chưa tìm thấy hướng tiến hóa phù hợp với bản thân. Ý nghĩa của hệ thống bảo đảm Mọi người đều có đường là không bỏ rơi bất kỳ nhà tiến hóa tiềm năng nào, và mở rộng nguồn nhân lực của văn minh càng nhiều càng tốt.</p><h3 id="_2-4-tien-hoa-pho-quat-la-nen-tang-cho-su-thang-chieu-cua-vu-tru" tabindex="-1">2.4 Tiến hóa phổ quát là nền tảng cho sự thăng chiều của vũ trụ <a class="header-anchor" href="#_2-4-tien-hoa-pho-quat-la-nen-tang-cho-su-thang-chieu-cua-vu-tru" aria-label="Permalink to &quot;2.4 Tiến hóa phổ quát là nền tảng cho sự thăng chiều của vũ trụ&quot;">​</a></h3><p>Sự thăng chiều toàn cục của vũ trụ không thể chỉ dựa vào một số cá nhân siêu mạnh, mà đòi hỏi sự tiến hóa phổ quát của chúng sinh Muôn tộc. Hiệu quả của mạng lưới Điểm Neo tương quan thuận với số lượng và chất lượng của các sự sống kết nối với mạng lưới. Khi càng nhiều sự sống kết nối với hệ thống tu luyện và nâng cao cấp độ, chu trình năng lượng và vận hành pháp tắc của toàn bộ mạng lưới Điểm Neo càng ổn định và hiệu quả, và quá trình thăng chiều của vũ trụ càng nhanh.</p><h2 id="_3-cau-truc-phan-cap-cua-he-thong-bao-đam" tabindex="-1">3. Cấu trúc phân cấp của Hệ thống Bảo đảm <a class="header-anchor" href="#_3-cau-truc-phan-cap-cua-he-thong-bao-đam" aria-label="Permalink to &quot;3. Cấu trúc phân cấp của Hệ thống Bảo đảm&quot;">​</a></h2><p>Hệ thống bảo đảm Mọi người đều có đường được chia thành bốn cấp độ, tạo thành một chuỗi bảo đảm hoàn chỉnh từ cơ bản đến nâng cao:</p><table tabindex="0"><thead><tr><th>Cấp độ</th><th>Tên</th><th>Nội dung bảo đảm</th><th>Phạm vi bao phủ</th></tr></thead><tbody><tr><td>Cấp độ thứ nhất</td><td>Bảo đảm cơ bản</td><td>Pháp môn tu luyện miễn phí, phân bổ tài nguyên tối thiểu, dịch vụ y tế và giáo dục cơ bản</td><td>Tất cả sự sống, không có ngưỡng vào</td></tr><tr><td>Cấp độ thứ hai</td><td>Hỗ trợ định hướng</td><td>Tài nguyên bổ sung, cố vấn, hỗ trợ công nghệ cho nhóm dễ bị tổn thương</td><td>Cá nhân và chủng tộc có tài năng ban đầu kém</td></tr><tr><td>Cấp độ thứ ba</td><td>Mở rộng cơ hội</td><td>Cơ hội tu luyện nâng cao, trao đổi giữa các vị diện, quyền tham gia dự án đặc biệt</td><td>Tu luyện giả có tiềm năng nhưng thiếu tài nguyên</td></tr><tr><td>Cấp độ thứ tư</td><td>Khuyến khích thành tựu</td><td>Tài nguyên cấp cao, truy cập nâng cao Điểm Neo, vinh dự văn minh</td><td>Tu luyện giả có đóng góp xuất sắc</td></tr></tbody></table><p>Cấp độ thứ nhất là &quot;đường cơ bản&quot;, đảm bảo không ai bị bỏ rơi; cấp độ thứ hai là &quot;bù đắp sự khác biệt&quot;, bù đắp cho sự khác biệt về tài năng ban đầu; cấp độ thứ ba là &quot;nuôi dưỡng tài năng&quot;, cho các cá nhân có tiềm năng nhiều cơ hội hơn; cấp độ thứ tư là &quot;khuyến khích&quot;, thưởng cho những người đóng góp xuất sắc. Bốn cấp độ tiến triển từng bước, cấu thành một hệ thống bảo đảm và khuyến khích hoàn chỉnh.</p><h2 id="_4-noi-dung-cu-the-cua-bao-đam-co-ban" tabindex="-1">4. Nội dung cụ thể của Bảo đảm cơ bản <a class="header-anchor" href="#_4-noi-dung-cu-the-cua-bao-đam-co-ban" aria-label="Permalink to &quot;4. Nội dung cụ thể của Bảo đảm cơ bản&quot;">​</a></h2><p>Bảo đảm cơ bản là cốt lõi của hệ thống Mọi người đều có đường, và cụ thể bao gồm các nội dung sau:</p><h3 id="_4-1-bao-đam-phap-mon-tu-luyen" tabindex="-1">4.1 Bảo đảm Pháp môn tu luyện <a class="header-anchor" href="#_4-1-bao-đam-phap-mon-tu-luyen" aria-label="Permalink to &quot;4.1 Bảo đảm Pháp môn tu luyện&quot;">​</a></h3><p>Các pháp môn cơ bản của Ba trăm hệ tu luyện Nguyên bản được mở cửa miễn phí cho tất cả các sự sống, không có bất kỳ ngưỡng vào nào. Mỗi sự sống có thể tự do lựa chọn hệ thống tu luyện phù hợp với bản thân, không cần trả phí, không cần tham gia vào một tông môn cụ thể, không cần thông qua xét nghiệm năng lực. Mạng lưới Điểm Neo cung cấp đánh giá khả năng tương thích của hệ thống, giúp tu luyện giả tìm ra con đường phù hợp nhất với bản thân.</p><h3 id="_4-2-bao-đam-tai-nguyen-tu-luyen" tabindex="-1">4.2 Bảo đảm Tài nguyên tu luyện <a class="header-anchor" href="#_4-2-bao-đam-tai-nguyen-tu-luyen" aria-label="Permalink to &quot;4.2 Bảo đảm Tài nguyên tu luyện&quot;">​</a></h3><p>Thông qua cơ chế hợp đồng liên sản và phân bổ tài nguyên công cộng, đảm bảo mỗi sự sống đều có được tài nguyên cần thiết để duy trì tu luyện cơ bản. Phân bổ tài nguyên cơ bản bao gồm: cung cấp năng lượng tối thiểu, dược phẩm tu luyện cơ bản, quyền sử dụng thiết bị tu luyện phổ thông. Đối với các vị diện thiếu tài nguyên, thực hiện phân bổ tài nguyên giữa các vị diện thông qua mạng lưới Điểm Neo.</p><h3 id="_4-3-bao-đam-moi-truong-tu-luyen" tabindex="-1">4.3 Bảo đảm Môi trường tu luyện <a class="header-anchor" href="#_4-3-bao-đam-moi-truong-tu-luyen" aria-label="Permalink to &quot;4.3 Bảo đảm Môi trường tu luyện&quot;">​</a></h3><p>Văn minh cộng sinh đã xây dựng các nơi tu luyện công cộng ở mỗi hành tinh và vị diện, bao gồm phòng tu luyện công cộng, khu vực điều chỉnh nồng độ năng lượng, phòng cảm thông pháp tắc, v.v. Những nơi này được mở cửa miễn phí hoặc giá rẻ cho tất cả các sự sống, đảm bảo ngay cả tu luyện giả nghèo nhất cũng có môi trường tu luyện phù hợp.</p><h3 id="_4-4-bao-đam-huong-dan-co-van" tabindex="-1">4.4 Bảo đảm Hướng dẫn Cố vấn <a class="header-anchor" href="#_4-4-bao-đam-huong-dan-co-van" aria-label="Permalink to &quot;4.4 Bảo đảm Hướng dẫn Cố vấn&quot;">​</a></h3><p>Xây dựng mạng lưới cố vấn giữa các chủng tộc, và các tu luyện giả cấp cao có nghĩa vụ cung cấp hướng dẫn cơ bản cho các tu luyện giả sơ cấp. Mỗi tu luyện giả sơ cấp có thể đăng ký ghép cặp cố vấn thông qua mạng lưới Điểm Neo, nhận được câu trả lời cơ bản cho các câu hỏi và lời khuyên tu luyện miễn phí. Đối với các tu luyện giả có khó khăn đặc biệt, cung cấp hướng dẫn định hướng một đối một.</p><h3 id="_4-5-bao-đam-phuc-hoi-y-te" tabindex="-1">4.5 Bảo đảm Phục hồi Y tế <a class="header-anchor" href="#_4-5-bao-đam-phuc-hoi-y-te" aria-label="Permalink to &quot;4.5 Bảo đảm Phục hồi Y tế&quot;">​</a></h3><p>Hệ thống y tế cộng sinh cung cấp dịch vụ y tế cơ bản và phục hồi sai lệch tu luyện miễn phí cho các tu luyện giả. Trong quá trình tu luyện, nếu bị thương, sai lệch tu luyện, rối loạn năng lượng, v.v., có thể nhận được điều trị và hỗ trợ phục hồi kịp thời, đảm bảo tu luyện giả không mất khả năng tiến hóa do tai nạn.</p><h2 id="_5-đoi-tuong-va-phuong-thuc-ho-tro-đinh-huong" tabindex="-1">5. Đối tượng và Phương thức Hỗ trợ định hướng <a class="header-anchor" href="#_5-đoi-tuong-va-phuong-thuc-ho-tro-đinh-huong" aria-label="Permalink to &quot;5. Đối tượng và Phương thức Hỗ trợ định hướng&quot;">​</a></h2><p>Hỗ trợ định hướng nhắm vào các nhóm dễ bị tổn thương sau:</p><ul><li><strong>Cá nhân tài năng thấp</strong>: Cá nhân có năng khiếu bẩm sinh kém, tiến độ tu luyện chậm, nhận được phân bổ tài nguyên bổ sung và hướng dẫn được cá nhân hóa</li><li><strong>Chủng tộc nghèo</strong>: Chủng tộc có sự thiếu hụt tài nguyên nói chung, mức độ tiến hóa thấp, nhận được hỗ trợ định hướng từ quỹ phát triển chủng tộc</li><li><strong>Nhóm sau thảm họa</strong>: Nhóm mất nhà cửa và tài nguyên do thảm họa vị diện, chiến tranh, v.v., nhận được cứu trợ khẩn cấp và hỗ trợ tái xây dựng</li><li><strong>Tu luyện giả khuyết tật</strong>: Tu luyện giả có khuyết tật thể chất hoặc tinh thần vì nhiều lý do, nhận được thiết bị hỗ trợ tu luyện đặc biệt và kế hoạch tu luyện tùy chỉnh</li><li><strong>Sự sống dị thường</strong>: Sự sống dị thường không phù hợp với hệ thống tu luyện thông thường, nhận được đánh giá đặc biệt và con đường tiến hóa tùy chỉnh</li></ul><p>Phương thức hỗ trợ định hướng bao gồm: phân bổ tài nguyên bổ sung, hướng dẫn cố vấn một đối một, kế hoạch tu luyện tùy chỉnh, cung cấp thiết bị đặc biệt, cơ hội trao đổi giữa các vị diện, v.v. Mục tiêu của hỗ trợ là giúp các nhóm dễ bị tổn thương đạt được mức độ tiến hóa cơ bản, và sau đó dần dần chuyển sang hệ thống phân phối Nhiều lao động Nhiều thưởng thông thường.</p><h2 id="_6-nguon-von-va-tai-nguyen-cua-he-thong-bao-đam" tabindex="-1">6. Nguồn vốn và tài nguyên của Hệ thống Bảo đảm <a class="header-anchor" href="#_6-nguon-von-va-tai-nguyen-cua-he-thong-bao-đam" aria-label="Permalink to &quot;6. Nguồn vốn và tài nguyên của Hệ thống Bảo đảm&quot;">​</a></h2><p>Việc vận hành hệ thống bảo đảm Mọi người đều có đường đòi hỏi nhiều tài nguyên và vốn, và các nguồn của nó bao gồm:</p><ol><li><strong>Thu nhập từ tài nguyên công cộng</strong>: Sản xuất từ các tài nguyên như mạch linh công cộng, mạch quặng năng lượng, điền dược, v.v., do văn minh cộng sinh quản lý trực tiếp</li><li><strong>Thuế điều chỉnh đóng góp</strong>: Thu một tỷ lệ nhất định &quot;thuế điều chỉnh đóng góp&quot; từ những người có đóng góp cao, được sử dụng cho việc vận hành hệ thống bảo đảm (thuế suất lũy tiến, tối đa không quá 30%)</li><li><strong>Quỹ phát triển văn minh</strong>: Năng lượng dư thừa tạo ra từ việc vận hành mạng lưới Điểm Neo, một phần được bơm vào quỹ phát triển văn minh</li><li><strong>Thu nhập từ cấp phép công nghệ</strong>: Phí sử dụng cấp phép của công nghệ kỹ thuật pháp tắc do văn minh cộng sinh sở hữu</li><li><strong>Quyên góp và di chúc</strong>: Quyên góp tự nguyện của cá nhân và chủng tộc</li></ol><p>Thu nhập và chi tiêu của hệ thống bảo đảm được quản lý bởi ủy ban bảo đảm thuộc Nghị viện Cộng hòa Muôn tộc, và tài khoản được công khai định kỳ cho tất cả các sự sống và chịu sự giám sát.</p><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Hệ thống bảo đảm Mọi người đều có đường là nền tảng của công bằng xã hội trong Văn minh Cộng sinh Neo. Nó đảm bảo rằng trong một văn minh lấy tu luyện và tiến hóa làm trung tâm, không có sự sống nào bị hệ thống tiến hóa bỏ rơi do xuất thân, tài năng hoặc nghèo đói. Mọi người đều có đường không có nghĩa là thực hiện bình quân chủ nghĩa, mà là cho mỗi sự sống một điểm xuất phát công bằng, một kênh đi lên, và một lời hứa không bị bỏ rơi. Dưới sự bảo đảm của Mọi người đều có đường, mỗi sự sống đều có thể tìm thấy con đường tiến hóa của riêng mình.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (Nguyên lý Phân phối Nhiều lao động Nhiều thưởng)</li><li>07-自生自长进化法则 (Quy luật Tiến hóa Tự sinh Tự trưởng)</li><li>38-共生医疗体系 (Hệ thống Y tế Cộng sinh)</li></ul>',43)])])}const s=h(g,[["render",a]]);export{b as __pageData,s as default};
